/* Measured hero compositions and visible product specifications. */
function archPanel(cls,col,row,w,h,content,label=''){return `<div class="arch-panel ${cls}" style="--col:${col};--row:${row};--cols:${w};--rows:${h}"${label?` aria-label="${label}"`:''}>${content}</div>`}
function archLines(){return `<div class="arch-guides" aria-hidden="true">${[4,11.6667,34.6667,50,65.3333,80.6667,96].map((p,i)=>`<i class="guide-v" style="--pos:${p}%;--delay:${.65+i*.06}s"></i>`).join('')}${[0,33.3333,41.6667,66.6667,75,100].map((p,i)=>`<i class="guide-h" style="--pos:${p}%;--delay:${.72+i*.06}s"></i>`).join('')}</div>`}
function architecturalHero(name,modifier){let art='';
if(modifier==='hero-color')art=archPanel('arch-color-pair',3,1,2,4,'<i></i><span>Lavender / Violet</span>')+archPanel('arch-color-pair pair-inverse',10,1,2,3,'<i></i>')+archPanel('arch-color-strip',8,9,5,2,'<i></i><i></i><i></i><i></i><i></i>')+archPanel('arch-color-pair pair-paper',4,10,2,3,'<i></i>');
if(modifier==='hero-typography')art=archPanel('arch-type-tile',1,1,2,4,'<span>TYPE</span>')+archPanel('arch-type-reading',10,1,3,4,'Clear words.<br>Bold ideas.<br>Room to<br>make more.')+archPanel('arch-type-symbols',8,10,3,3,'Aa Bb<br>012345<br>&amp;@!?')+archPanel('arch-type-toolbar',7,5,2,1,'<b>B</b><em>I</em><span>↔</span>');
if(modifier==='hero-iconography')art=archPanel('arch-icon-stack',2,1,4,4,`<div class="stack-sheet"></div><div class="stack-sheet"></div><div class="stack-sheet main-sheet"><span class="arch-mini-label">3 projects</span><div class="stack-thumbs"><span>${icon('image')}</span><span>${icon('type')}</span><span>${icon('layers')}</span></div><div class="stack-project">${icon('folder')}<strong>Brand exploration<small>Private workspace</small></strong></div></div>`)+archPanel('arch-tool-rail',12,1,1,5,`<span>${icon('plus')}<small>Create</small></span><span>${icon('settings')}<small>Settings</small></span><span>${icon('download')}<small>Export</small></span>`)+archPanel('arch-context-menu',2,10,2,3,`<span>${icon('cursor')} Edit</span><span>${icon('layers')} Duplicate</span><span>${icon('handoff')} Handoff</span>`)+archPanel('arch-image-icon',10,10,3,3,icon('image'));
if(modifier==='hero-imagery')art=archPanel('arch-landscape',9,1,4,4,'<img src="assets/brand-packaging.png" alt="Lavender presentation box and printed packaging">')+archPanel('arch-gradient',3,2,3,3,'<img src="assets/brand-paint.png" alt="Physical painted brand artwork">')+archPanel('arch-landscape landscape-detail',2,10,5,3,'<img src="assets/brand-wear.png" alt="Lavender cap and cream printed shirt">')+archPanel('arch-image-artifact',10,10,3,3,'<img class="merch-thumb" src="assets/brand-objects.png" alt="Ceramic and glass still life"><span>Material study<small>Objects / Studio</small></span>');
if(modifier==='hero-motion')art=archPanel('arch-motion-curve',7,3,5,7,'<svg viewBox="0 0 400 400" fill="none" aria-hidden="true"><path class="curve-axis" d="M20 20H380V380H20Z"/><path class="curve-main" pathLength="1" d="M20 380C20 40 380 380 380 20"/><circle cx="20" cy="380" r="5"/><circle cx="380" cy="20" r="5"/></svg><span>cubic-bezier(0.22, 1, 0.36, 1)</span>')+archPanel('arch-mini-action',10,11,3,2,`${icon('folder')}<span>Create project</span>`)+archPanel('arch-motion-tool',3,2,1,1,icon('cursor'));
if(modifier==='hero-voice')art=archPanel('arch-voice-note',3,1,3,3,'Your idea.<br>A place to begin.')+archPanel('arch-voice-note note-inverse',10,2,3,3,'Clear.<br>Encouraging.<br>Honest.')+archPanel('arch-message',8,10,4,3,`${icon('check')}<strong>Your brand kit is ready.</strong><span>Review the colors and type.</span>`);
if(modifier==='hero-form')art=archPanel('arch-form-spec',9,2,3,3,'<div></div><span>16 px / Brand panel</span>')+archPanel('arch-form-input',2,2,4,2,'<label>Project name</label><div>A new perspective</div>')+archPanel('arch-form-button',3,10,3,2,'<span>Create project</span><small>6 px / Control</small>')+archPanel('arch-form-spec form-card',9,10,3,3,`${icon('image')}<span>10 px / Product card</span>`);
if(modifier==='hero-applications')art=archPanel('arch-product-capture',8,1,5,4,'<img src="assets/product-concept.svg" alt="Product dashboard concept">')+archPanel('arch-launch-tile',2,1,3,3,'From a thought.<br>To a thing.')+archPanel('arch-presentation-tile',8,10,4,3,'<img src="assets/presentation.svg" alt="Presentation title using the brand identity">');
return `<section class="express-hero architectural-hero ${modifier}">${archLines()}<div class="arch-content">${art}</div><h1>${name}</h1></section>`}
function specTable(title,caption,headers,rows,cls=''){return `<section class="product-specs ${cls}"><div class="specs-heading"><span class="eyebrow">Usage reference</span><h2>${title}</h2><p>${caption}</p></div><div class="specs-scroll" role="region" aria-label="${title} table" tabindex="0"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((cell,i)=>`<${i===0?'th scope="row"':'td'}>${cell}</${i===0?'th':'td'}>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
function colorChip(hex){return `<span class="spec-color"><i style="background:${hex}"></i><code>${hex}</code></span>`}
function visibleSpecs(id){if(id==='color')return specTable('A role for every color.','Use semantic roles in the dashboard. These values change with the theme.',['Role','Light mode','Dark mode','Use it for'],[
['Canvas',colorChip('#FAF9F7'),colorChip('#17151D'),'Workspace background. The largest surface area.'],['Elevated surface',colorChip('#FFFFFF'),colorChip('#23202C'),'Cards, panels, menus and dialogs.'],['Primary text',colorChip('#221F2C'),colorChip('#F6F3FA'),'Headings, body copy and essential labels.'],['Secondary text',colorChip('#625B6E'),colorChip('#BFB9CA'),'Supporting descriptions and secondary metadata.'],['Primary action',colorChip('#6646D8'),colorChip('#C7B5F5'),'Create, generate and save. One dominant action per view.'],['Action label',colorChip('#FAF9F7'),colorChip('#221F2C'),'Text on the primary action color.'],['Input boundary',colorChip('#797083'),colorChip('#918A9D'),'Visible boundaries for fields and essential controls.'],['Decorative divider',colorChip('#DED9E5'),colorChip('#4D465B'),'Non-interactive grouping and separation.']])+specTable('Expression and status.','Keep expression separate from feedback. Every status also needs a label or icon.',['Group','Value / pair','Example','Usage'],[
['Brand expression',colorChip('#D9C9F7'),'<span class="spec-badge lavender-badge">Ink on Lavender</span>','Lavender backgrounds with Ink text. Posters, image framing and selected brand moments.'],['Success',colorChip('#176B43'),'<span class="spec-status success">✓ Saved</span>','Completed actions. Dark mode: #9DDFC3.'],['Warning',colorChip('#885B00'),'<span class="spec-status warning">! Review needed</span>','Recoverable issues requiring attention. Dark mode: #F2CD7C.'],['Error',colorChip('#B93239'),'<span class="spec-status error">× Couldn’t save</span>','Failed actions and validation. Dark mode: #FFADB0.'],['Information',colorChip('#255EB8'),'<span class="spec-status info">i Draft</span>','Helpful non-critical information. Dark mode: #ABC9FF.']]);
if(id==='typography')return specTable('Type, with a purpose.','A clear hierarchy for a working product. Brand display sizes can scale with the viewport.',['Role / specimen','Family','Size / line','Weight','Product usage'],[
['<span class="type-spec-display">Big ideas.</span>','Manrope','64 / 68','800','Short brand statements and launch moments.'],['<span class="type-spec-title">Your workspace</span>','Manrope','32 / 38','700','Primary page title. One per screen.'],['<span class="type-spec-heading">Recent projects</span>','Manrope','24 / 30','700','Major content sections and panel headings.'],['<span class="type-spec-sub">Brand exploration</span>','DM Sans','18 / 26','600','Card titles, supporting headings and grouped content.'],['<span class="type-spec-body">A place for your next idea.</span>','DM Sans','16 / 24','400','Descriptions, instructions and reading text.'],['<span class="type-spec-label">Create project</span>','DM Sans','14 / 20','500','Buttons, navigation, tabs and form labels.'],['<span class="type-spec-meta">Edited today</span>','DM Sans','12 / 18','400','Secondary timestamps and non-essential metadata only.'],['<code>color.action.primary</code>','IBM Plex Mono','14 / 21','400','Code, tokens and technical values.']],'type-reference');
if(id==='foundations')return specTable('Form follows the task.','Use a small, consistent set of measurements.',['Group','Value','Usage'],[['Control radius','6 px','Buttons, fields and compact product controls.'],['Card radius','10 px','Project cards and reusable product containers.'],['Brand panel radius','16 px','Larger expressive panels and artwork framing.'],['Spacing scale','4, 8, 12, 16, 24, 32, 48, 64 px','A 4 px base for alignment, grouping and hierarchy.'],['Decorative divider','1 px','Non-interactive separation.'],['Focus outline','3 px with visible offset','Keyboard focus on both light and dark surfaces.']]);
if(id==='motion')return specTable('A rhythm for the task.','The dashboard responds quickly; brand compositions can take more time.',['Motion group','Timing','Usage'],[['Feedback','180 ms','Buttons, toggles and immediate state feedback.'],['Transition','280 ms','Panels, menus and content changes.'],['Brand expression','800 ms','Compositions and signature brand moments.'],['Reduced motion','Resolved states','Remove spatial travel, continuous drift and parallax.']]);
if(id==='applications')return specTable('One identity, used with intention.','The context determines the amount of expression.',['Application','Emphasis','Usage'],[['Product dashboard','Clarity and task hierarchy','Neutral surfaces, readable type, one clear action and restrained accents.'],['Launch artwork','Expression and recognition','Larger type, tonal imagery, purposeful crops and more expressive motion.'],['Presentation','Hierarchy and space','One main message per slide, a clear title and deliberate supporting imagery.']]);
if(id==='voice')return specTable('The right tone for the moment.','Keep the words useful and the next step clear.',['Context','Tone','Example'],[['Starting','Open and encouraging','Create a project to get started.'],['Success','Calm and specific','Your brand kit is ready. Review the colors and type.'],['Error','Direct and considerate','We couldn’t save your changes. Your draft is still here. Try saving again.'],['Actions','Concrete and brief','Create project / Export image / Review brand kit']]);
return ''}
function withVisibleSpecs(html,id){const table=visibleSpecs(id);return table?html.replace('<section class="usage-section">',table+'<section class="usage-section">'):html}
function newImageryExperience(){return architecturalHero('Imagery','hero-imagery')+statementScene('Different subjects. Different styles. A shared point of view.','imagery-words')+`<section class="scenic-editorial"><div class="scenic-heading"><span class="meta">Objects / Places / Ideas</span><h2>Made to live<br>beyond the screen.</h2></div><figure class="scenic-wide"><img src="assets/brand-carry.png" alt="Violet DesignOS canvas tote and lavender branded zip pouch"><figcaption>Carry / canvas, color and a clear wordmark</figcaption></figure><div class="scenic-pair"><figure class="scenic-gradient"><img src="assets/landscape-violet.png" alt="Violet dusk coastline with warm peach light"><figcaption>Place / one atmospheric landscape</figcaption></figure><figure class="scenic-crop"><img src="assets/brand-print.png" alt="Risograph-style graphic prints on a cobalt desk"><figcaption>Print / graphic composition and tactile ink</figcaption></figure></div></section><section class="imagery-in-product"><div><span class="meta">In context</span><h2>Physical inspiration.<br>A focused workspace.</h2></div><div class="scenic-project-card"><img src="assets/brand-laptop.png" alt="Laptop displaying a DesignOS creative workspace"><div><span class="meta">Brand exploration</span><h3>The creative workspace</h3><p>Product direction · Concept</p><span class="spec-badge">Project cover</span></div></div><div class="scenic-launch"><span>DesignOS / Creative practice</span><h3>Make room<br>for what’s next.</h3><img src="assets/gradient-field.svg" alt="Lavender and violet light field supporting a launch composition"></div></section>`+specTable('Different subjects. One point of view.','Every placement uses a different image. Connect varied subjects through palette, lighting and composition.',['Image group','Treatment','Usage','Keep in mind'],[['Bags & pouches','Tactile canvas, considered print placement, clear wordmark.','Brand campaigns, project covers, merchandise concepts.','Show seams, scale and believable materials.'],['Apparel & caps','Embroidery, restrained print and wearable color pairings.','Studio collections, campaign imagery, brand applications.','Keep typography legible; avoid filling every surface.'],['Paint & material','Physical brushwork, pigment and recognizable material texture.','Editorial features, expressive launch artwork, cover images.','Use a few palette colors with generous breathing room.'],['Places & light','One landscape or designed light field with a clear focal point.','Atmospheric backgrounds and expressive compositions.','Use once; do not repeat alternate crops as new images.'],['Packaging & objects','Printed paper, ceramics, glass and deliberate studio styling.','Editorial compositions and brand application studies.','Choose a distinct subject and background for each placement.'],['Product captures','Accurate interfaces with believable task content.','Feature communication and workflow demonstrations.','Preserve legibility. Label illustrative concepts.']])+usage('A brand with a life of its own.','Choose a subject first. Let the identity give it a shared character.',[['Art direction','<p>Build a varied collection of totes, apparel, packaging, physical objects, prints, paintings, landscapes and product photography. Use a distinct asset for every image placement; avoid repeating the same image at different crops. Use violet and lavender as anchors, with coral, amber or blue accents where useful. No people are required. Avoid repeating the same subject or crop throughout a page.</p>'],['Assets & generation','<p>These AI-generated studio mockups, landscape and artwork explore the provisional DesignOS identity. They demonstrate art direction, not manufactured merchandise.</p><a class="text-link" href="assets/brand-carry.png" download>Download bags</a> · <a class="text-link" href="assets/brand-wear.png" download>Download apparel</a> · <a class="text-link" href="assets/brand-paint.png" download>Download artwork</a> · <a class="text-link" href="assets/brand-packaging.png" download>Packaging</a> · <a class="text-link" href="assets/brand-objects.png" download>Objects</a> · <a class="text-link" href="assets/brand-print.png" download>Prints</a> · <a class="text-link" href="assets/brand-laptop.png" download>Workspace</a>']])+next('imagery')}
function scrollRow(title,subtitle,items,kind){return `<section class="icon-showcase"><div class="showcase-heading"><div><span class="meta">${kind}</span><h2>${title}</h2><p>${subtitle}</p></div><div class="scroller-controls"><button data-slide="-1" aria-label="Previous ${title} examples">Previous</button><button data-slide="1" aria-label="Next ${title} examples">Next</button></div></div><div class="icon-track" role="region" aria-label="${title} examples" tabindex="0">${items.join('')}</div></section>`}
function iconMarquee(){const names=Object.keys(paths).filter(n=>!['sun','moon'].includes(n));const row=(title,size,kind,items,direction)=>`<div class="icon-band"><div class="icon-band-heading"><h2>${title}</h2><span>${size}</span></div><div class="icon-loop ${kind}" data-icon-loop data-direction="${direction}" tabindex="0" role="region" aria-label="${title}. Drag or use left and right arrow keys to explore."><div class="icon-loop-belt">${[0,1,2].map(copy=>`<div class="icon-loop-set" ${copy?'aria-hidden="true"':''}>${items}</div>`).join('')}</div></div></div>`;return `<section class="icon-catalogue"><div class="icon-catalogue-top"><div><span class="meta">One family. Every scale.</span><h2 class="icon-catalogue-title">The icon family.</h2></div><button class="icon-loop-toggle" aria-pressed="false">Pause motion</button></div>${row('Spot icons','120 × 120 px','spot',names.map(n=>`<span class="icon-loop-item" title="${n}">${icon(n)}</span>`).join(''),1)}${row('Pictograms','64 × 64 px','picto',names.slice().reverse().map(n=>`<span class="icon-loop-item" title="${n}">${icon(n)}</span>`).join(''),-1)}${row('UI icons','24 × 24 px','ui', [['folder','Create folder'],['settings','Adjust'],['download','Export'],['image','Edit image'],['clock','Recents'],['cursor','Select'],['type','Add text'],['layers','Layers'],['search','Search'],['handoff','Handoff'],['plus','New project'],['heart','Favorite'],['globe','Brands'],['chat','Ask AI']].map(([n,t])=>`<span class="icon-loop-chip">${icon(n)}<strong>${t}</strong></span>`).join(''),1)}<p class="icon-loop-hint">Drag in either direction to explore. Motion pauses while you interact.</p></section>`}
function newIconExperience(){return architecturalHero('Iconography','hero-iconography')+iconMarquee()+scrollRow('See the action, in place.','Navigation, actions and feedback, shown where they belong.',[
`<article class="icon-context-card"><span class="icon-card-label">Navigation</span><div class="example-sidebar"><strong>Your workspace</strong><span class="selected">${icon('grid')} Home</span><span>${icon('folder')} Projects</span><span>${icon('image')} Assets</span><span>${icon('globe')} Brands</span></div></article>`,
`<article class="icon-context-card"><span class="icon-card-label">Project actions</span><div class="example-menu"><span>${icon('cursor')} Edit</span><span>${icon('layers')} Duplicate</span><span>${icon('download')} Export</span></div><span class="icon-card-note">Labels clarify the action.</span></article>`,
`<article class="icon-context-card"><span class="icon-card-label">Empty state</span><div class="example-empty">${icon('folder')}<strong>Your next idea starts here.</strong><span>Create a project to begin.</span><span class="example-create">${icon('plus')} New project</span></div></article>`,
`<article class="icon-context-card"><span class="icon-card-label">Feedback</span><div class="example-feedback"><span>${icon('check')} Changes saved</span><span>${icon('clock')} Generating image…</span><span>${icon('close')} Couldn’t save changes</span></div><span class="icon-card-note">A status icon always has a label.</span></article>`,
`<article class="icon-context-card"><span class="icon-card-label">Toolbar</span><div class="example-toolbar">${['cursor','type','image','layers','settings'].map(n=>`<span>${icon(n)}</span>`).join('')}</div><div class="toolbar-caption">Icon-only controls use accessible names,<br>visible focus and generous hit areas.</div></article>`],'In context')+specTable('A scale for every context.','Use optical judgment at small sizes. The stroke stays consistent within each control group.',['Group','Icon size','Label / spacing','Usage'],[
['Compact utilities','16 px','14 px label / 6–8 px gap','Dense metadata, small inline actions and secondary utilities.'],['Product controls','20 px','14 px label / 8 px gap','Navigation, buttons, menus and toolbars. Default for the dashboard.'],['Roomier controls','24 px','16 px label / 8–12 px gap','Prominent controls, cards and comfortable navigation.'],['Illustrative states','32–48 px','Heading + supporting copy','Empty states, onboarding and explanatory content. Not a button-size rule.']])+usage('Make the meaning obvious.','A consistent visual vocabulary for product actions, navigation and feedback.',[['Construction','<p>24 px base grid, 1.75 px base stroke, rounded joins and caps. Scale to 16, 20, 24 or 32 px with optical checks. Avoid mixing unrelated filled and outline families.</p>'],['Accessibility','<p>Icon-only controls require an accessible name, visible focus and at least a 44 px touch target where practical. Pair unfamiliar actions with text. Status colors must also have labels or icons.</p>']])+next('iconography')}
function bindArchitecture(root){const cleanups=[];$$('.icon-showcase',root).forEach(section=>{const track=$('.icon-track',section),buttons=$$('[data-slide]',section);const sync=()=>buttons.forEach(b=>{const start=track.scrollLeft<2,end=track.scrollLeft+track.clientWidth>=track.scrollWidth-3;b.disabled=+b.dataset.slide<0?start:end});buttons.forEach(b=>b.onclick=()=>track.scrollBy({left:+b.dataset.slide*Math.min(track.clientWidth*.85,650),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));track.addEventListener('scroll',sync,{passive:true});sync();cleanups.push(()=>track.removeEventListener('scroll',sync))});return ()=>cleanups.forEach(f=>f())}

const previousArchitectureBinding=bindArchitecture;
bindArchitecture=function(root){const dispose=previousArchitectureBinding(root),rows=[...root.querySelectorAll('[data-icon-loop]')],cleanups=[];const media=matchMedia('(prefers-reduced-motion: reduce)');let paused=media.matches||document.documentElement.classList.contains('motion-reduced');const toggle=root.querySelector('.icon-loop-toggle');function label(){if(toggle){toggle.textContent=paused?'Play motion':'Pause motion';toggle.setAttribute('aria-pressed',String(paused))}}if(toggle)toggle.onclick=()=>{paused=!paused;label()};label();const states=rows.map(el=>{let x=0,drag=false,hover=false,lastX=0;const belt=el.firstElementChild;function draw(){const w=belt.firstElementChild.getBoundingClientRect().width;if(!w)return;x=((x%w)+w)%w;belt.style.transform=`translate3d(${-x-w}px,0,0)`}const down=e=>{if(e.button!==0)return;drag=true;lastX=e.clientX;el.setPointerCapture(e.pointerId);el.classList.add('dragging')};const move=e=>{if(!drag)return;x-=e.clientX-lastX;lastX=e.clientX;draw()};const up=()=>{drag=false;el.classList.remove('dragging')};const enter=()=>hover=true,leave=()=>hover=false;const key=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();x+=e.key==='ArrowRight'?100:-100;draw()}};for(const [n,f] of [['pointerdown',down],['pointermove',move],['pointerup',up],['pointercancel',up],['pointerenter',enter],['pointerleave',leave],['keydown',key]]){el.addEventListener(n,f);cleanups.push(()=>el.removeEventListener(n,f))}draw();return{tick(dt){if(!paused&&!drag&&!hover&&!el.contains(document.activeElement)){x+=dt*Number(el.dataset.direction)*30;draw()}}}});let frame,last=performance.now();function tick(now){const dt=Math.min((now-last)/1000,.05);last=now;if(!document.hidden)states.forEach(s=>s.tick(dt));frame=requestAnimationFrame(tick)}frame=requestAnimationFrame(tick);return()=>{cancelAnimationFrame(frame);cleanups.forEach(f=>f());dispose()}}
